import { createHash } from 'node:crypto';
import { Type } from 'typebox';
import type { KenanTool, ToolContext } from '../types.js';
import { answeringChat } from '../agents/origin.js';

/** Unambiguous UTF-8 commitment; salt is generated by the server, not the caller. */
export const guessHash = (salt: string, guess: string, topic: string | null = null): string => createHash('sha256').update(JSON.stringify(topic === null ? ['seal-guess-v1', salt, guess] : ['seal-guess-v2', salt, topic, guess]), 'utf8').digest('hex');

/** Never send a prediction in tool arguments to a chat client, including partial drafts. */
export function publicToolArgs(name: string, args: unknown): unknown {
  if (name !== 'seal_guess') return args;
  const a = args as { action?: unknown; id?: unknown; topic?: unknown; score?: unknown } | null;
  return { ...(a?.action !== undefined ? { action: a.action } : {}), ...(a?.id !== undefined ? { id: a.id } : {}), ...(a?.topic !== undefined ? { topic: a.topic } : {}), ...(a?.score !== undefined ? { score: a.score } : {}) };
}

export function sealGuessTool({ deps, person, agent }: ToolContext): KenanTool {
  return {
    name: 'seal_guess', files: 'none', records: 'writes', label: 'Sealed guess',
    description: 'Commit a prediction without showing it to your person. action seal takes an optional public topic (always give a short label; not secret and included in the commitment) and guess (include odds and why if wanted) and posts a lock card in the chat your current turn answers, or chatId. The server generates a salt, SHA256 commitment and timestamp; no guess appears in the card or visible tool arguments. Keep your narration and thinking free of hints. After the person answers, reveal with the full id or its first 8 characters when unique and optional score called (✅ called it) or missed (❌ missed). Reveal updates the same card and the server checks its hash. Neither guess nor reveal/score can be edited through this tool. list returns the latest 50 cards in that chat, with no unrevealed guess. Records live in the server database, not editable local guess files; this does not protect against a trusted host administrator changing the database or server code.',
    parameters: Type.Object({
      action: Type.Union([Type.Literal('seal'), Type.Literal('reveal'), Type.Literal('list')]),
      guess: Type.Optional(Type.String({ minLength: 1, maxLength: 20_000 })),
      topic: Type.Optional(Type.String({ minLength: 1, maxLength: 500 })),
      id: Type.Optional(Type.String()), chatId: Type.Optional(Type.String()),
      score: Type.Optional(Type.Union([Type.Literal('called'), Type.Literal('missed')])),
    }),
    execute: async (callId, raw) => {
      const args = raw as { action: 'seal' | 'reveal' | 'list'; guess?: string; topic?: string; id?: string; chatId?: string; score?: 'called' | 'missed' };
      const chatId = args.chatId ?? answeringChat(agent, deps.runtime.turnOf(agent.id));
      let value: unknown;
      if (args.action === 'list') {
        value = { items: (await deps.store.listSealedGuesses(person.id, chatId)).flatMap(m => m.parts.filter(p => p.type === 'seal')) };
      } else {
        if (args.action === 'seal' && (!args.guess?.trim() || args.guess.length > 20_000)) throw new Error('seal_guess_required: seal needs a non-empty guess of at most 20000 characters');
        if (args.action === 'seal' && args.topic !== undefined && (!args.topic.trim() || args.topic.length > 500)) throw new Error('seal_topic_invalid: topic must be 1–500 characters');
        if (args.action === 'reveal' && !args.id) throw new Error('seal_id_required: reveal needs the full id or its first 8 characters');
        const message = args.action === 'seal'
          ? await deps.store.sealGuess({ ownerId: person.id, authorId: agent.id, conversationId: chatId, callId, guess: args.guess!, topic: args.topic })
          : await deps.store.revealGuess(person.id, args.id!, args.score);
        deps.bus.toConversation(message.conversationId, { type: 'message', message });
        value = message.parts.find(p => p.type === 'seal');
      }
      return { content: [{ type: 'text', text: JSON.stringify(value) }], details: {} };
    },
  };
}
